 const helpOptions=()=>{if(answers.goal?.want==='Python 入门')return [['带我跑通第一个脚本','一个可运行的简单脚本'],['陪我排查一个报错','一份错误原因与修改说明'],['一起整理代码思路','一份能自己继续修改的代码']];return support[answers.goal?.domain||'ai'];};
 modal('Loop一下','<div class="loop-wizard" id="loop-wizard"></div>','<div class="wizard-footer"><button class="text-link" id="wizard-back" type="button">上一步</button><span>找到适合你的下一步</span></div>');
 $('.modal').classList.add('wizard-modal');
