 const options=step===0?goals.map((g,i)=>({index:i,label:g.label,symbol:g.symbol,selected:answers.goal===g})):step===1?stages.map((g,i)=>({index:i,label:g.label,detail:g.detail,selected:answers.stage===i})):helpOptions().map((g,i)=>({index:i,label:g[0],detail:g[1],selected:answers.help===i}));
