 $('#loop-wizard').innerHTML=`<div class="wizard-progress" aria-label="第 ${step+1} 题，共 3 题">${[0,1,2].map(i=>`<i class="${i<=step?'active':''}"></i>`).join('')}<span>${step+1} / 3</span></div><section class="wizard-card" aria-labelledby="wizard-question"><span class="wizard-eyebrow">${heading}</span><h3 id="wizard-question" tabindex="-1">${titles[step]}</h3><div class="wizard-options ${step===0?'goals':''}">${options.map(o=>`<button class="wizard-option ${o.selected?'selected':''}" data-choice="${o.index}" type="button">${o.symbol?`<span class="wizard-option-icon">${icon(o.symbol)}</span>`:''}<span><strong>${esc(o.label)}</strong>${o.detail?`<small>${esc(o.detail)}</small>`:''}</span>${icon('chevron')}</button>`).join('')}</div></section>`;
 $$('#loop-wizard [data-choice]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.choice);if(step===0){if(answers.goal!==goals[i]){answers.stage=null;answers.help=null;}answers.goal=goals[i];}else if(step===1){answers.stage=i;}else answers.help=i;step++;paint();});
